void FAnimationRuntime::ConvertPoseToMeshRotation(FCompactPose& LocalPose)
{
	SCOPE_CYCLE_COUNTER(STAT_ConvertPoseToMeshRot);

#if INTEL_ISPC
	if (bAnim_ConvertPoseToMeshRotation_ISPC_Enabled)
	{
		UE_AUTORTFM_OPEN_NO_VALIDATION // Open writes are recorded
		{
			AutoRTFM::RecordOpenWrite(
				LocalPose.GetMutableBones().GetData(),
				LocalPose.GetNumBones() * sizeof(FTransform));
			ispc::ConvertPoseToMeshRotation(
				reinterpret_cast<ispc::FTransform*>(LocalPose.GetMutableBones().GetData()),
				reinterpret_cast<const int32*>(LocalPose.GetBoneContainer().GetCompactPoseParentBoneArray().GetData()),
				LocalPose.GetNumBones());
		};
	}
	else
#endif
	{
		for (FCompactPoseBoneIndex BoneIndex(1); BoneIndex < LocalPose.GetNumBones(); ++BoneIndex)
		{
			const FCompactPoseBoneIndex ParentIndex = LocalPose.GetParentBoneIndex(BoneIndex);

			const FQuat MeshSpaceRotation = LocalPose[ParentIndex].GetRotation() * LocalPose[BoneIndex].GetRotation();
			LocalPose[BoneIndex].SetRotation(MeshSpaceRotation);
		}
	}
}

void FAnimationRuntime::ConvertMeshRotationPoseToLocalSpace(FCompactPose& Pose)
{
	SCOPE_CYCLE_COUNTER(STAT_ConvertMeshRotPoseToLocalSpace);

#if INTEL_ISPC
	if (bAnim_ConvertMeshRotationPoseToLocalSpace_ISPC_Enabled)
	{
		UE_AUTORTFM_OPEN_NO_VALIDATION // Open writes are recorded
		{
			AutoRTFM::RecordOpenWrite(
				Pose.GetMutableBones().GetData(),
				Pose.GetNumBones() * sizeof(FTransform));
			ispc::ConvertMeshRotationPoseToLocalSpace(
				reinterpret_cast<ispc::FTransform*>(Pose.GetMutableBones().GetData()),
				reinterpret_cast<const int32*>(Pose.GetBoneContainer().GetCompactPoseParentBoneArray().GetData()),
				Pose.GetNumBones());
		};
	}
	else
#endif
	{
		for (FCompactPoseBoneIndex BoneIndex(Pose.GetNumBones() - 1); BoneIndex > 0; --BoneIndex)
		{
			const FCompactPoseBoneIndex ParentIndex = Pose.GetParentBoneIndex(BoneIndex);

			FQuat LocalSpaceRotation = Pose[ParentIndex].GetRotation().Inverse() * Pose[BoneIndex].GetRotation();
			Pose[BoneIndex].SetRotation(LocalSpaceRotation);
		}
	}
}

void FAnimationRuntime::AccumulateAdditivePose(FAnimationPoseData& BaseAnimationPoseData, const FAnimationPoseData& AdditiveAnimationPoseData, float Weight, enum EAdditiveAnimationType AdditiveType)
{
	if (AdditiveType == AAT_RotationOffsetMeshSpace)
	{
		AccumulateMeshSpaceRotationAdditiveToLocalPoseInternal(BaseAnimationPoseData.GetPose(), AdditiveAnimationPoseData.GetPose(), Weight);
	}
	else
	{
		AccumulateLocalSpaceAdditivePoseInternal(BaseAnimationPoseData.GetPose(), AdditiveAnimationPoseData.GetPose(), Weight);
	}

	// if curve exists, accumulate with the weight, 
	BaseAnimationPoseData.GetCurve().Accumulate(AdditiveAnimationPoseData.GetCurve(), Weight);

	UE::Anim::Attributes::AccumulateAttributes(AdditiveAnimationPoseData.GetAttributes(), BaseAnimationPoseData.GetAttributes(), Weight, AdditiveType);

	// normalize
	BaseAnimationPoseData.GetPose().NormalizeRotations();
}

void FAnimationRuntime::AccumulateLocalSpaceAdditivePoseInternal(FCompactPose& BasePose, const FCompactPose& AdditivePose, float Weight)
{
	if (FAnimWeight::IsRelevant(Weight))
	{
		const ScalarRegister VBlendWeight(Weight);
		if (FAnimWeight::IsFullWeight(Weight))
		{
#if INTEL_ISPC
			if (bAnim_AccumulateLocalSpaceAdditivePose_ISPC_Enabled)
			{
				UE_AUTORTFM_OPEN_NO_VALIDATION // Open writes are recorded
				{
					AutoRTFM::RecordOpenWrite(
						BasePose.GetMutableBones().GetData(),
						BasePose.GetNumBones() * sizeof(FTransform));
					ispc::AccumulateWithAdditiveScale(
						reinterpret_cast<ispc::FTransform*>(BasePose.GetMutableBones().GetData()),
						reinterpret_cast<const ispc::FTransform*>(AdditivePose.GetBones().GetData()),
						Weight,
						BasePose.GetNumBones());
				};
			}
			else
#endif
			{
				// fast path, no need to weight additive.
				for (FCompactPoseBoneIndex BoneIndex : BasePose.ForEachBoneIndex())
				{
					BasePose[BoneIndex].AccumulateWithAdditiveScale(AdditivePose[BoneIndex], VBlendWeight);
				}
			}
		}
		else
		{
			// Slower path w/ weighting
			for (FCompactPoseBoneIndex BoneIndex : BasePose.ForEachBoneIndex())
			{
				// copy additive, because BlendFromIdentityAndAccumulate modifies it.
				FTransform Additive = AdditivePose[BoneIndex];
				FTransform::BlendFromIdentityAndAccumulate(BasePose[BoneIndex], Additive, VBlendWeight);
			}
		}
	}
}

void FAnimationRuntime::AccumulateMeshSpaceRotationAdditiveToLocalPoseInternal(FCompactPose& BasePose, const FCompactPose& MeshSpaceRotationAdditive, float Weight)
{
	SCOPE_CYCLE_COUNTER(STAT_AccumulateMeshSpaceRotAdditiveToLocalPose);

	if (FAnimWeight::IsRelevant(Weight))
	{
		// Convert base pose from local space to mesh space rotation.
		FAnimationRuntime::ConvertPoseToMeshRotation(BasePose);

		// Add MeshSpaceRotAdditive to it
		FAnimationRuntime::AccumulateLocalSpaceAdditivePoseInternal(BasePose, MeshSpaceRotationAdditive, Weight);

		// Convert back to local space
		FAnimationRuntime::ConvertMeshRotationPoseToLocalSpace(BasePose);
	}
}

ENGINE_API void FAnimationRuntime::AccumulateRootSpaceAdditivePoseInternal(FCompactPose& BasePose, const FCompactPose& RootSpaceAdditivePose, float Weight)
{
	if (FAnimWeight::IsRelevant(Weight))
	{		
		// Cache off the Root Transform and Zero it Out
		FCompactPoseBoneIndex BoneIndex(0);
		FTransform RootTransform = BasePose[BoneIndex];
		BasePose[BoneIndex] = FTransform::Identity;

		// Convert base pose from local space to mesh space rotation.
		FAnimationRuntime::ConvertPoseToMeshRotation(BasePose);

		// Add MeshSpaceRotAdditive to it
		FAnimationRuntime::AccumulateLocalSpaceAdditivePoseInternal(BasePose, RootSpaceAdditivePose, Weight);

		// Convert back to local space
		FAnimationRuntime::ConvertMeshRotationPoseToLocalSpace(BasePose);

		// Restore the original Root Transform
		BasePose[BoneIndex] = RootTransform;

	const bool bExpectsAdditivePose=true;
	FPoseContext AdditiveEvalContext(Output, bExpectsAdditivePose);

	Base.Evaluate(Output);
	Additive.Evaluate(AdditiveEvalContext);

	FAnimationPoseData BaseAnimationPoseData(Output);
	const FAnimationPoseData AdditiveAnimationPoseData(AdditiveEvalContext);


	if (bRootSpaceAdditive)
	{
		FAnimationRuntime::AccumulateRootSpaceRotationAdditiveToLocalPose(BaseAnimationPoseData, AdditiveAnimationPoseData, ActualAlpha);
	}
	else
	{
		FAnimationRuntime::AccumulateAdditivePose(BaseAnimationPoseData, AdditiveAnimationPoseData, ActualAlpha, AAT_RotationOffsetMeshSpace);
	}

	Output.Pose.NormalizeRotations();
}
else
{
	Base.Evaluate(Output);
}

* When we create additive, we create additive scale based on [TargetScale/SourceScale -1]
* because that way when you apply weight of 0.3, you don't shrink. We only saves the % of grow/shrink
* when we apply that back to it, we add back the 1, so that it goes back to it.
* This solves issue where you blend two additives with 0.3, you don't come back to 0.6 scale, but 1 scale at the end
* because [1 + [1-1]*0.3 + [1-1]*0.3] becomes 1, so you don't shrink by applying additive scale
*
* Note: Rotation will not be normalized! Will have to be done manually.
*
* @param Atom The other transform to accumulate into this one
* @param BlendWeight The weight to multiply Atom by before it is accumulated.
*/
inline void AccumulateWithAdditiveScale(const TTransform<T>& Atom, const ScalarRegister& BlendWeightScalar)
{
	const TransformVectorRegister BlendWeight(BlendWeightScalar.Value);
	const TransformVectorRegister DefaultScale = GlobalVectorConstants::Float1110;

	// SourceAtom = Atom * BlendWeight;
	const TransformVectorRegister BlendedRotation = VectorMultiply(Atom.Rotation, BlendWeight);

	// Rotation = SourceAtom.Rotation * Rotation;
	Rotation = VectorQuaternionMultiply2(BlendedRotation, Rotation);

	// Translation += SourceAtom.Translation;
	// Scale *= SourceAtom.Scale;
	Translation = VectorMultiplyAdd(Atom.Translation, BlendWeight, Translation);
	Scale3D = VectorMultiply(Scale3D, VectorMultiplyAdd(Atom.Scale3D, BlendWeight, DefaultScale));


	DiagnosticCheckNaN_All();
}

/**
 * Set the translation and Scale3D components of this transform to a linearly interpolated combination of two other transforms
 *
 * Translation = FMath::Lerp(SourceAtom1.Translation, SourceAtom2.Translation, Alpha)
 * Scale3D = FMath::Lerp(SourceAtom1.Scale3D, SourceAtom2.Scale3D, Alpha)
 *
 * @param SourceAtom1 The starting point source atom (used 100% if Alpha is 0)

use std::collections::{HashMap, HashSet};

use bevy::prelude::*;
use bevy_animation_graph::core::{
    animation_graph::TimeUpdate,
    animation_node::{NodeLike, ReflectNodeLike},
    context::{new_context::NodeContext, spec_context::SpecContext},
    edge_data::DataSpec,
    errors::GraphError,
    pose::{BonePose, Pose, RootMotionDelta},
    skeleton::Skeleton,
};

const ALPHA_THRESHOLD: f32 = 1e-6;

#[derive(Reflect, Clone, Debug, Default)]
#[reflect(Default, NodeLike)]
#[type_path = "als_ext"]
pub struct MeshSpaceAdditiveNode;

impl MeshSpaceAdditiveNode {
    pub const FACTOR: &'static str = "factor";
    pub const IN_POSE_A: &'static str = "pose_a";
    pub const IN_TIME_A: &'static str = "time_a";
    pub const IN_POSE_B: &'static str = "pose_b";
    pub const IN_TIME_B: &'static str = "time_b";
    pub const OUT_POSE: &'static str = "pose";
}

fn blend_additive_rotation(base: Quat, additive: Quat, alpha: f32) -> Quat {
    let identity_sign = if additive.w >= 0.0 { 1.0 } else { -1.0 };
    let weighted = Quat::from_xyzw(
        additive.x * alpha,
        additive.y * alpha,
        additive.z * alpha,
        identity_sign * (1.0 - alpha) + additive.w * alpha,
    )
    .normalize();
    (weighted * base).normalize()
}

fn merge_translation(base: Option<Vec3>, additive: Option<Vec3>, alpha: f32) -> Option<Vec3> {
    match (base, additive) {

        if !visited.insert(bone) {
            return;
        }
        if let Some(parent) = skeleton.parent(&bone) {
            visit(skeleton, parent, visited, order);
        }
        order.push(bone);
    }

    let mut visited = HashSet::default();
    let mut order = Vec::new();
    visit(skeleton, skeleton.root(), &mut visited, &mut order);
    for bone in skeleton.iter_bones() {
        visit(skeleton, bone, &mut visited, &mut order);
    }
    order
}

pub(crate) fn materialize_missing_reference_bones(base: &mut Pose, skeleton: &Skeleton) {
    for bone in skeleton.iter_bones() {
        if bone == skeleton.root() || base.paths.contains_key(&bone) {
            continue;
        }
        let Some(transform) = skeleton.default_transforms(bone) else {
            continue;
        };
        base.add_bone(BonePose::from_transform(transform.local), bone);
    }
}

fn base_local_rotation(
    base: &Pose,
    skeleton: &Skeleton,
    bone: bevy_animation_graph::core::pose::BoneId,
) -> Quat {
    base.paths
        .get(&bone)
        .and_then(|index| base.bones.get(*index))
        .and_then(|pose| pose.rotation)
        .or_else(|| {
            skeleton
                .default_transforms(bone)
                .map(|transform| transform.local.rotation)
        })
        .unwrap_or(Quat::IDENTITY)
}

fn additive_rotation(
    additive: &Pose,
    bone: bevy_animation_graph::core::pose::BoneId,
) -> Option<Quat> {
    additive
        .paths
        .get(&bone)
        .and_then(|index| additive.bones.get(*index))

pub fn apply_mesh_space_additive(
    base: &mut Pose,
    additive: &Pose,
    alpha: f32,
    skeleton: &Skeleton,
) {
    if alpha.abs() <= ALPHA_THRESHOLD {
        return;
    }

    materialize_missing_reference_bones(base, skeleton);

    for (bone, additive_index) in &additive.paths {
        let additive_bone = &additive.bones[*additive_index];
        if let Some(base_index) = base.paths.get(bone).copied() {
            merge_non_rotation(&mut base.bones[base_index], additive_bone, alpha);
        } else {
            let mut base_bone = skeleton
                .default_transforms(*bone)
                .map(|transform| BonePose {
                    translation: Some(transform.local.translation),
                    rotation: Some(transform.local.rotation),
                    scale: Some(transform.local.scale),
                    weights: None,
                })
                .unwrap_or_default();
            merge_non_rotation(&mut base_bone, additive_bone, alpha);
            base.add_bone(base_bone, *bone);
        }
    }

    let hierarchy = hierarchy_order(skeleton);
    let mut mesh_rotations: HashMap<bevy_animation_graph::core::pose::BoneId, Quat> =
        HashMap::default();
    for bone in &hierarchy {
        let local = base_local_rotation(base, skeleton, *bone);
        let rotation = skeleton
            .parent(bone)
            .and_then(|parent| mesh_rotations.get(&parent).copied())
            .map(|parent| parent * local)
            .unwrap_or(local);
        mesh_rotations.insert(*bone, rotation);
    }

    for bone in &hierarchy {
        if let (Some(rotation), Some(additive_rotation)) = (
            mesh_rotations.get(bone).copied(),
            additive_rotation(additive, *bone),
        ) {
            mesh_rotations.insert(
                *bone,
                blend_additive_rotation(rotation, additive_rotation, alpha),
            );
        }
    }

    for bone in hierarchy.iter().rev() {
        let Some(rotation) = mesh_rotations.get(bone).copied() else {
            continue;
        };
        let local = skeleton
            .parent(bone)
            .and_then(|parent| mesh_rotations.get(&parent).copied())
            .map(|parent| parent.inverse() * rotation)
            .unwrap_or(rotation)
            .normalize();
        if let Some(base_index) = base.paths.get(bone).copied() {
            base.bones[base_index].rotation = Some(local);
        }
    }

    base.root_motion = merge_root_motion(
        base.root_motion.clone(),
        additive.root_motion.clone(),
        alpha,
    );
}
